<template>
 <view class="secondary-page has-footer">
  <PrototypePageHeader :title="view==='ADMINS'?'组织管理员设置':'组织成员'" icon="people"/>
  <template v-if="view==='ADMINS'">
   <view class="section">
    <view class="segmented"><button :class="{active:adminTab==='SCHOOL'}" :disabled="busy||!schoolOrg" @tap="switchAdminTab('SCHOOL')">学校管理员</button><button :class="{active:adminTab==='INSTITUTION'}" :disabled="busy||!institutionOrg" @tap="switchAdminTab('INSTITUTION')">机构管理员</button></view>
    <text v-if="error" class="error">{{error}}</text>
    <view v-if="busy" class="empty">正在处理…</view>
    <view v-for="item in admins" :key="item.id" class="row">
     <view class="person"><PrototypeIcon name="user" :size="35"/></view>
     <view class="person-copy"><view class="row-top"><text class="name">{{item.displayName||item.username}}</text><text v-if="item.owner" class="badge owner">超级管理员</text><text v-else class="badge class-admin">班级管理员</text></view><text v-if="item.organizationNames?.length" class="meta">{{item.organizationNames.join(' / ')}}</text></view>
     <text :class="['admin-state',item.status==='ENABLED'?'enabled':'disabled']">{{item.status==='ENABLED'?'已启用':'未启用'}}</text>
    </view>
    <view v-if="!busy&&!admins.length&&!error" class="empty"><PrototypeIcon name="people" tone="muted" :size="64"/><text>暂无管理员</text></view>
   </view>
   <view class="section add-admin-card" @tap="openMemberPicker">
    <text class="add-plus">＋</text>
    <text class="add-title">添加管理员</text>
    <text class="add-note">仅可设置本组织内的管理员，不可跨学校或其他机构设置</text>
   </view>
   <view class="bottom-actions"><text class="small">管理员 {{admins.length}} 人</text></view>
  </template>
  <template v-else>
  <view class="section">
   <text class="field-label">当前组织</text>
   <picker :range="organizations" range-key="name" :value="organizationIndex" :disabled="busy" @change="chooseOrganization"><view class="picker-field"><text>{{organization?.name||'请选择管理组织'}}</text><text>⌄</text></view></picker>
   <view class="segmented"><button :class="{active:side==='MEMBERS'}" :disabled="busy" @tap="switchSide('MEMBERS')">已加入</button><button v-if="can('ORG_MEMBER_ASSOCIATE')" :class="{active:side==='CANDIDATES'}" :disabled="busy" @tap="switchSide('CANDIDATES')">待加入</button></view>
   <view class="search-row"><PrototypeIcon name="people" :size="30"/><input v-model="keyword" placeholder="姓名、账号或手机号" :disabled="busy" @confirm="search"/><button class="secondary" :disabled="busy" @tap="search">查询</button></view>
  </view>
  <text v-if="error" class="error">{{error}}</text>
  <view class="section">
   <view v-if="!parent" class="back-row"><text class="back-link" @tap="backToAdmins">‹ 返回管理员列表</text></view>
   <view class="section-heading"><text class="section-title">{{side==='MEMBERS'?'组织成员':'待加入成员'}}</text><text class="small">共 {{total}} 人</text></view>
   <view v-if="busy" class="empty">正在处理…</view>
   <view v-for="item in items" :key="item.id" class="row">
    <view class="person"><PrototypeIcon name="user" :size="35"/></view>
    <view class="person-copy"><view class="row-top"><text class="name">{{item.displayName||item.username}}</text><text v-if="item.owner" class="badge owner">负责人</text><text v-else-if="item.administrator" class="badge">管理员</text></view><text class="meta">{{item.mobile||item.username}}</text><text v-if="item.organizationNames?.length" class="meta">{{item.organizationNames.join(' / ')}}</text></view>
    <checkbox v-if="!item.owner" :checked="selected.includes(item.id)" :disabled="busy" color="#184f40" @tap="toggle(item.id)"/>
   </view>
   <view v-if="!busy&&!items.length&&!error" class="empty"><PrototypeIcon name="people" tone="muted" :size="64"/><text>{{side==='MEMBERS'?'暂无组织成员':'暂无待加入成员'}}</text></view>
   <view v-if="total>20" class="paging"><button :disabled="busy||page===1" @tap="move(-1)">上一页</button><text>第 {{page}} 页</text><button :disabled="busy||page*20>=total" @tap="move(1)">下一页</button></view>
  </view>
  <view class="bottom-actions"><text class="small">已选择 {{selected.length}} 人</text><view class="action-grid"><button v-if="side==='CANDIDATES'&&can('ORG_MEMBER_ASSOCIATE')" class="primary" :disabled="busy||!selected.length" @tap="act('members:associate')">加入组织</button><template v-if="side==='MEMBERS'"><button v-if="can('ORG_ADMIN_ASSIGN')" class="primary" :disabled="busy||!selected.length" @tap="act('administrators:assign')">设管理员</button><button v-if="can('ORG_ADMIN_REVOKE')" class="secondary" :disabled="busy||!selected.length" @tap="act('administrators:revoke')">撤销管理员</button><button v-if="can('ORG_MEMBER_REMOVE')" class="danger" :disabled="busy||!selected.length" @tap="act('members:remove')">移除</button></template></view></view>
  </template>
 </view>
</template>
<script setup lang="ts">
import PrototypePageHeader from "@/components/PrototypePageHeader.vue";
import {computed,ref} from 'vue';import {onShow,onHide,onUnload,onLoad} from '@dcloudio/uni-app';import PrototypeIcon from '@/components/PrototypeIcon.vue';import {getOrganizationSession} from '@/session/organization-session';import {request} from '@/api/http';import {getParentSession} from '@/session/parent-session';import {onboardingApi,type MyOrganization} from '@/api/organization-onboarding';import {organizationMembersApi,type OrganizationMember,type OrganizationAdmin,type MemberAction} from '@/api/organization-members';
const parent=ref(false);const session=()=>parent.value?getParentSession():getOrganizationSession();const meContext=(token:string)=>request<{permissionCodes:string[]}>('/auth/me',{header:{Authorization:`Bearer ${token}`}});const organizations=ref<MyOrganization[]>([]),allOrgs=ref<MyOrganization[]>([]),organizationIndex=ref(0),permissions=ref<string[]>([]),side=ref<'MEMBERS'|'CANDIDATES'>('MEMBERS'),view=ref<'ADMINS'|'MEMBERS'>('MEMBERS'),adminTab=ref<'SCHOOL'|'INSTITUTION'>('SCHOOL'),admins=ref<OrganizationAdmin[]>([]),keyword=ref(''),items=ref<OrganizationMember[]>([]),selected=ref<string[]>([]),page=ref(1),total=ref(0),busy=ref(false),error=ref('');const organization=computed(()=>organizations.value[organizationIndex.value]);const schoolOrg=computed(()=>allOrgs.value.find(o=>o.typeCode==='SCHOOL'));const institutionOrg=computed(()=>allOrgs.value.find(o=>o.typeCode==='TRAINING_INSTITUTION'));const adminOrg=computed(()=>adminTab.value==='SCHOOL'?schoolOrg.value:institutionOrg.value);let epoch=0,requestedOrganization='';const can=(code:string)=>permissions.value.includes(code);const valid=(n:number,t:string)=>n===epoch&&session()?.accessToken===t;
onLoad(q=>{parent.value=q?.identity==='parent';view.value=q?.identity==='parent'?'MEMBERS':'ADMINS';requestedOrganization=q?.organizationId||'';});function hide(){epoch++;busy.value=false;selected.value=[];items.value=[];admins.value=[];permissions.value=[];organizations.value=[];allOrgs.value=[];error.value="";total.value=0;}onHide(hide);onUnload(hide);
onShow(async()=>{permissions.value=[];organizations.value=[];allOrgs.value=[];items.value=[];admins.value=[];selected.value=[];const s=session();if(!s){uni.reLaunch({url:'/pages/unified-login/unified-login'});return;}const n=++epoch;busy.value=true;error.value='';try{const [me,orgs]=await Promise.all([meContext(s.accessToken),onboardingApi.organizations(s.accessToken)]);if(!valid(n,s.accessToken))return;permissions.value=me.permissionCodes;if(!can('ORG_MEMBER_READ'))throw new Error('当前账号没有组织成员查看权限');organizations.value=orgs.filter(o=>parent.value?o.typeCode==='FAMILY'&&o.canEnterFamily:o.canEnterInstitution);allOrgs.value=orgs;const stored=uni.getStorageSync('lingdong.selected-organization') as {accessToken?:string;organizationId?:string};const id=requestedOrganization||(stored?.accessToken===s.accessToken?stored.organizationId:'');if(requestedOrganization&&!organizations.value.some(o=>o.id===requestedOrganization))throw new Error('目标组织不在当前账号真实成员范围内');organizationIndex.value=Math.max(0,organizations.value.findIndex(o=>o.id===id));if(!organizations.value.length)throw new Error('当前账号没有可进入的组织');if(!parent.value)view.value='ADMINS';}catch(e){if(valid(n,s.accessToken))error.value=e instanceof Error?e.message:'加载失败';}finally{if(valid(n,s.accessToken))busy.value=false;}if(valid(n,s.accessToken)&&!error.value){if(view.value==='ADMINS')await loadAdmins();else await load();}});
async function load(){const s=session(),org=organization.value;if(!s||!org||busy.value)return;const n=++epoch;busy.value=true;error.value='';selected.value=[];items.value=[];try{const result=await organizationMembersApi.list(s.accessToken,org.id,side.value,keyword.value,page.value);if(valid(n,s.accessToken)){items.value=result.items;total.value=result.total;}}catch(e){if(valid(n,s.accessToken))error.value=e instanceof Error?e.message:'成员加载失败';}finally{if(valid(n,s.accessToken))busy.value=false;}}
function toggle(id:string){if(busy.value)return;selected.value=selected.value.includes(id)?selected.value.filter(v=>v!==id):[...selected.value,id];}
async function loadAdmins(){const s=session(),org=adminOrg.value;if(!s||busy.value)return;if(!org){error.value='当前账号没有学校或机构组织';return;}const n=++epoch;busy.value=true;error.value='';admins.value=[];try{const result=await organizationMembersApi.listAdministrators(s.accessToken,org.id);if(valid(n,s.accessToken))admins.value=result;}catch(e){if(valid(n,s.accessToken))error.value=e instanceof Error?e.message:'管理员加载失败';}finally{if(valid(n,s.accessToken))busy.value=false;}}
function switchAdminTab(value:'SCHOOL'|'INSTITUTION'){if(busy.value)return;adminTab.value=value;loadAdmins();}function openMemberPicker(){if(busy.value)return;view.value='MEMBERS';page.value=1;load();}function backToAdmins(){if(busy.value)return;view.value='ADMINS';loadAdmins();}function chooseOrganization(e:{detail:{value:string}}){if(busy.value)return;organizationIndex.value=Number(e.detail.value);page.value=1;load();}function switchSide(value:'MEMBERS'|'CANDIDATES'){if(busy.value)return;side.value=value;page.value=1;load();}function search(){page.value=1;load();}function move(by:number){page.value+=by;load();}
async function act(action:MemberAction){const s=session(),org=organization.value;if(!s||!org||busy.value||!selected.value.length)return;const codes:Record<MemberAction,string>={'members:associate':'ORG_MEMBER_ASSOCIATE','members:remove':'ORG_MEMBER_REMOVE','administrators:assign':'ORG_ADMIN_ASSIGN','administrators:revoke':'ORG_ADMIN_REVOKE'};if(!can(codes[action]))return;const ids=selected.value.filter(id=>!items.value.find(i=>i.id===id)?.owner);if(!ids.length)return;const before=epoch;busy.value=true;if(action!=='members:associate'){const result=await uni.showModal({title:'确认组织成员操作',content:`将对选中的 ${ids.length} 位成员执行此操作`,confirmText:'确认'});if(!result.confirm||before!==epoch||session()?.accessToken!==s.accessToken){if(before===epoch)busy.value=false;return;}}const n=++epoch;let succeeded=false;error.value="";busy.value=true;try{const me=await meContext(s.accessToken);if(!valid(n,s.accessToken))return;if(!me.permissionCodes.includes(codes[action]))throw new Error('当前操作权限已失效');await organizationMembersApi.action(s.accessToken,org.id,action,ids);if(valid(n,s.accessToken)){succeeded=true;uni.showToast({title:'操作成功',icon:'success'});}}catch(e){if(valid(n,s.accessToken))error.value=e instanceof Error?e.message:'操作失败';}finally{if(valid(n,s.accessToken))busy.value=false;}if(succeeded&&valid(n,s.accessToken)){if(action==='administrators:assign'){view.value='ADMINS';await loadAdmins();}else await load();}}
</script>
<style scoped>
.secondary-page,.prototype-workspace{padding:24rpx 28rpx 60rpx;min-height:calc(100vh - var(--window-top,0px));box-sizing:border-box;background:#f6f9f5;color:#172e25}.has-footer,.has-tabbar{padding-bottom:160rpx}.prototype-section-header{display:flex;justify-content:center;align-items:center;gap:12rpx;margin:-24rpx -28rpx 24rpx;padding:28rpx;background:linear-gradient(120deg,#206b52,#0c4f3e);color:white;font-size:32rpx;font-weight:650}.section,.form-band,.band,.heading-band{background:#fff;border:1rpx solid #e4ece3;border-radius:24rpx;padding:26rpx;margin-bottom:22rpx}.segmented,.mode-control,.tabs,.action-grid,.form-actions,.paging,.search-row,.two-columns{display:flex;align-items:center;gap:14rpx;margin:18rpx 0}.segmented button,.mode-control button,.tab,.action-grid button{flex:1}.active{background:#e2f2e6;color:#0a774d}.field-label{display:block;font-size:26rpx;margin:20rpx 0 12rpx}.picker-field,.picker-value,.field,input,textarea{background:#f7faf6;border:1rpx solid #dfe8dc;border-radius:16rpx;padding:18rpx;font-size:26rpx;box-sizing:border-box}.picker-field{display:flex;justify-content:space-between}.search-row input{flex:1;min-width:0}textarea{width:100%;min-height:180rpx}.row,.request-person,.invitation-class{display:flex;align-items:center;gap:18rpx;padding:24rpx 0;border-bottom:1rpx solid #e8eee6}.person{width:80rpx;height:80rpx;border-radius:50%;background:#e2eee3;display:flex;align-items:center;justify-content:center;flex-shrink:0}.person-copy{flex:1;min-width:0}.row-top,.section-heading,.detail-line,.list-head{display:flex;justify-content:space-between;align-items:center;gap:12rpx}.name,.section-title,.title,.form-title{font-size:30rpx;font-weight:650}.meta,.small,.counter{display:block;font-size:23rpx;color:#778179;line-height:1.7}.badge,.status{border-radius:12rpx;background:#e2f4e7;color:#13734d;padding:4rpx 12rpx;font-size:23rpx}.PENDING,.submitted{background:#fff0cb;color:#b37a20}.detail-line{font-size:25rpx;padding:15rpx 0}.error,.danger{color:#ac4e42}.empty,.state,.state-text{padding:30rpx;text-align:center;font-size:25rpx;color:#7c867d}.empty text{display:block}.bottom-actions{position:fixed;bottom:0;left:0;right:0;background:#fff;padding:24rpx 28rpx calc(24rpx + env(safe-area-inset-bottom));border-top:1rpx solid #e2ebe0;z-index:4}.qr-content{text-align:center;padding:28rpx 0}.invite-code{display:block;font-size:38rpx;font-weight:700;letter-spacing:2rpx;margin:20rpx 0}.block-action{width:100%;margin-top:24rpx}.list-band{background:#fff;border-radius:24rpx;padding:20rpx}.list-row,.record-row,.history-row{border-bottom:1rpx solid #e6ede4;padding:24rpx 0}button{font-size:26rpx;line-height:1.5;margin:0;padding:16rpx 22rpx;background:#eaf2e8;color:#24583d;border-radius:16rpx}button::after{border:0}.primary,.submit-button,.save-button{background:#176f50;color:white}.secondary,.outline{background:#f2f6ef;color:#28563e}.required{color:#ba5b4c}.reason-input,.textarea{width:100%}.badge.owner{background:#fdeada;color:#b06c51}.badge.class-admin{background:#e3edfb;color:#2f6bbf}.admin-state{font-size:24rpx;flex-shrink:0}.admin-state.enabled{color:#137c53}.admin-state.disabled{color:#c2803d}.add-admin-card{display:flex;flex-direction:column;align-items:center;gap:8rpx;padding:44rpx 26rpx;text-align:center}.add-plus{font-size:44rpx;color:#176f50}.add-title{font-size:30rpx;font-weight:650;color:#176f50}.add-note{font-size:23rpx;color:#778179}.back-row{margin-bottom:8rpx}.back-link{font-size:24rpx;color:#176f50}.row-top .name{flex:1;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.row-top .badge{flex-shrink:0;white-space:nowrap}.admin-state{white-space:nowrap;margin-left:8rpx}
</style>
